// Loads the canonical site.json export generated by the Python pipeline
// (`python -m apertus_eval_prep site`). Every number displayed in the UI
// traces back to that file; nothing is hardcoded in the frontend.
//
// Stale-data rule: optionals may be null (PENDING / unavailable). The UI
// must render those as "Not measured" / "Unavailable", never as 0.

export interface SiteCell {
  run_id: string
  model_id: string
  model_label: string
  factor: string
  factor_level: string
  config_key: string
  config_hash: string | null
  experiment_id: string | null
  status: "MEASURED" | "SAMPLED" | "PENDING" | string
  provenance: string
  n: number | null
  correct: number | null
  accuracy: number | null
  accuracy_ci95: [number, number] | null
  axes: Record<string, string | number | boolean | null>
  tasks: Record<string, { n?: number; correct?: number; accuracy?: number | null; ci95?: [number, number] | null }>
  latency: { e2e_ms_mean?: number; e2e_ms_p95?: number; ttft_ms_mean?: number; ttft_ms_p50?: number; tokens_per_sec_mean?: number; n?: number } | null
  git_commit: string | null
  utc: string | null
  path: string | null
}

export interface RankingMember {
  model_id: string
  model_label: string
  score: number
  rank: number
  n: number | null
  ci95: [number, number] | null
  run_id: string
  factor: string
  factor_level: string
}

export interface RankingComparison {
  base_key: string
  variant_key: string
  factor: string
  factor_level: string
  n_shared_models: number
  excluded_from_base: string[]
  members: {
    model_id: string
    model_label: string
    base_score: number
    variant_score: number
    delta: number | null
    base_rank: number
    variant_rank: number
    rank_move: number
    ci95: [number, number] | null
  }[]
  base_order: string[]
  variant_order: string[]
  tau: number | null
  n_reversals: number
  reordered: boolean
  provenance: string
}

export interface StatComparison {
  model_id: string
  model_label: string
  base_key: string
  variant_key: string
  factor: string
  factor_level: string
  n_paired: number
  n_dropped: number
  base_accuracy: number | null
  variant_accuracy: number | null
  delta: number | null
  delta_ci95: [number | null, number | null]
  ci_excludes_zero: boolean | null
  perm_p: number | null
  perm_p_holm: number | null
  perm_p_bh: number | null
  mcnemar: { a_correct_b_wrong: number; a_wrong_b_correct: number; disagreement_rate: number | null; chi2: number; p_value: number }
  cohens_h: number | null
  provenance: string
}

export interface SiteData {
  schema_version: number
  generated_utc: string
  registry: string
  coverage: {
    n_rows: number; n_cells: number; measured: number; sampled: number
    pending: number; planned_cells: number | null; completion: number | null
    n_models: number; n_configs: number; n_factors: number; factors: string[]
    provenance: string
  }
  models: { model_id: string; label: string; n_cells: number; mean_accuracy: number | null; min_accuracy: number | null; max_accuracy: number | null; spread: number | null; provenance: string }[]
  configs: { config_key: string; factor: string; factor_level: string; n_models: number; n_pending: number; models: string[]; provenance: string }[]
  cells: SiteCell[]
  rankings: { config_key: string; factor: string; factor_level: string; n_models: number; ranking: RankingMember[]; ranks: number[]; models: string[]; provenance: string }[]
  ranking_comparisons: RankingComparison[]
  statistics: {
    base_key: string; n_comparisons: number; n_tests_corrected: number
    n_boot: number; n_perm: number; seed: number
    comparisons: StatComparison[]; methods: string[]; provenance: string
  }
  reliability: {
    ers: number | null
    components: Record<string, number | null>
    components_used: string[]
    weights_used: Record<string, number>
    n_components: number
    bootstrap: { mean_tau: number | null; p_any_reversal: number | null; n_models: number; n_configs: number }
    models: string[]
    excluded_models: string[]
    n_configs_in_matrix: number
    skipped_configs: string[]
    ablation: Record<string, { ers_without: number | null; delta: number | null }>
    disclaimer: string
    provisional: boolean
  }
  failures: {
    run_id: string; model_id: string; model_label: string; config_key: string
    total: number; counts: Record<string, number>; rates: Record<string, number | null>
    failure_rate: number | null
    per_task: Record<string, { total: number } & Record<string, number>>
    artifact_present: boolean; provenance: string
  }[]
  pareto: {
    frontier: ParetoPoint[]; dominated: ParetoPoint[]; excluded: ParetoPoint[]
    x_key: string; y_key: string; provenance: string
  }
  reproducibility: {
    git_commit: string | null; n_verified: number; n_pass: number; n_fail: number
    rows: { run_id: string; config_hash: string | null; all_match: boolean; failed: string[] }[]
    detail: Record<string, { run_id: string; checks: { name: string; expected: unknown; observed: unknown; match: boolean | null }[]; all_match: boolean }>
    commands: Record<string, { sweep_command: string; eval_command_hint: string }>
    provenance: string
  }
  provenance_legend: Record<string, string>
}

export interface ParetoPoint {
  label: string; model_label: string; config_key: string
  latency_ms: number | null; accuracy: number | null; tts: number | null
  pareto: string
}

// Resolve data under the deployed base path (vite `base`), so the bundled
// app works both at "/" in dev and at "/apertus-eval-prep/" on GitHub Pages.
const BASE = `${import.meta.env.BASE_URL}data`

export async function loadSite(): Promise<SiteData> {
  const res = await fetch(`${BASE}/site/site.json`)
  if (!res.ok) throw new Error(`failed to load site.json: ${res.status}`)
  return res.json() as Promise<SiteData>
}

/** "Not measured" for missing numerics — never render null as 0. */
export function fmtPct(x: number | null | undefined, digits = 2): string {
  if (x === null || x === undefined || Number.isNaN(x)) return "Not measured"
  return `${(x * 100).toFixed(digits)}%`
}

export function fmtDelta(x: number | null | undefined, digits = 2): string {
  if (x === null || x === undefined || Number.isNaN(x)) return "Not measured"
  const pp = x * 100
  return `${pp >= 0 ? "+" : ""}${pp.toFixed(digits)} pp`
}

export function fmtP(x: number | null | undefined): string {
  if (x === null || x === undefined || Number.isNaN(x)) return "Not applicable"
  if (x < 0.001) return "< 0.001"
  return x.toFixed(3)
}

/** Short model label: 'Qwen/Qwen2.5-3B-Instruct' -> 'Qwen-3B'. */
export function shortLabel(modelId: string): string {
  const base = modelId.split("/").pop() ?? modelId
  const bits = base.split("-")
  if (bits.length >= 2) return `${bits[0]}-${bits[1]}`
  return base
}
